SELECT c.c_customer_id, CASE WHEN c.c_preferred_cust_flag = 'N' THEN 'Preferred' ELSE 'Regular' END AS cust_status, (c.c_birth_year * 10000 + c.c_birth_month * 100 + c.c_birth_day) AS birthdate_num, wp.wp_char_count + wp.wp_link_count * 2 - wp.wp_image_count AS page_metric, CASE WHEN wp.wp_type = 'dynamic                                           ' THEN 'HomePage' WHEN wp.wp_type = 'order                                             ' THEN 'ProductPage' ELSE 'OtherPage' END AS page_type_desc, CASE WHEN c.c_birth_year < 1940 THEN 'Senior' ELSE 'Junior' END AS age_group, CASE WHEN wp.wp_max_ad_count > 2 THEN 'HighAds' WHEN wp.wp_max_ad_count > 4 THEN 'MediumAds' ELSE 'LowAds' END AS ad_level FROM customer c JOIN web_page wp ON wp.wp_customer_sk = c.c_customer_sk WHERE c.c_birth_year > 1937 AND wp.wp_type = 'ad                                                '
